    def dijkstra(start, end):
        dist = [float('inf')] * n
        dist[start] = 0
        visited = [False] * n
        heap = [(0, start)]

        while heap:
            curr_dist, u = heapq.heappop(heap)
            if visited[u]:
                continue
            visited[u] = True
            if u == end:
                return curr_dist
            for v, w in graph[u]:
                if not visited[v] and dist[v] > curr_dist + w:
                    dist[v] = curr_dist + w
                    heapq.heappush(heap, (dist[v], v))
        return -1 if dist[end] == float('inf') else dist[end]

    # Check all possible (s, t) pairs
    result = []
    for s in range(n):
        for t in range(n):
            if s == t:
                result.append(0)
            else:
                result.append(dijkstra(s, t))

    # Return the result as a list where result[i] is the shortest path from i to i
    return result

