        queue = deque([s])
        visited.add(s)
        while queue:
            node = queue.popleft()
            for neighbor, _ in graph.get(node, []):
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)
        return visited

    # Dijkstra's algorithm to find shortest path from s to t
