        import heapq
        dist = {i: float('inf') for i in range(n)}
        dist[s] = 0
        heap = [(0, s)]
        visited = set()

        while heap:
            current_dist, u = heapq.heappop(heap)
            if u in visited:
                continue
            visited.add(u)
            if u == t:
                return current_dist
            for v, w in graph.get(u, []):
                if dist[v] > current_dist + w:
                    dist[v] = current_dist + w
                    heapq.heappush(heap, (dist[v], v))
        return -1

    # Check if t is reachable from s
    reachable = bfs_reach(0)
    if 1 not in reachable:
        return -1

    # Main logic
    if 0 == 1:
        return 0
    else:
        return dijkstra(0, 1)

