def solve(n, edges):
    from collections import defaultdict, deque

    # Build adjacency list
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    # Dijkstra's algorithm to find shortest path from s to t
    def dijkstra(s, t):
        dist = [float('inf')] * n
        dist[s] = 0
        visited = [False] * n
        pq = [(0, s)]

        while pq:
            current_dist, u = heapq.heappop(pq)
            if visited[u]:
                continue
            visited[u] = True
            if u == t:
                return current_dist
            for v, w in graph[u]:
                if not visited[v] and dist[v] > current_dist + w:
                    dist[v] = current_dist + w
                    heapq.heappush(pq, (dist[v], v))
        return -1 if dist[t] == float('inf') else dist[t]

    # Check all possible starting and ending nodes
    result = -1
    for s in range(n):
        for t in range(n):
            if s == t:
                result = max(result, 0)
            else:
                result = max(result, dijkstra(s, t))

    return result

