def solve(n, edges):
    from collections import defaultdict, deque

    # Build adjacency list
    adj = defaultdict(list)
    for u, v, w in edges:
        adj[u].append((v, w))

    # Dijkstra's algorithm to find shortest path from s to t
    def dijkstra(start, end):
        dist = [float('inf')] * n
        dist[start] = 0
        visited = [False] * n
        heap = [(0, start)]

        while heap:
            current_dist, u = heapq.heappop(heap)
            if visited[u]:
                continue
            visited[u] = True
            if u == end:
                return current_dist
            for v, w in adj[u]:
                if not visited[v] and dist[v] > current_dist + w:
                    dist[v] = current_dist + w
                    heapq.heappush(heap, (dist[v], v))
        return -1  # No path found

    # Try all possible starting points and find the minimum path
    min_weight = float('inf')
    for s in range(n):
        for t in range(n):
            if s == t:
                min_weight = min(min_weight, 0)
            else:
                result = dijkstra(s, t)
                if result != -1:
                    min_weight = min(min_weight, result)

    return min_weight if min_weight != float('inf') else -1

