def solve(n, edges):
    from collections import defaultdict, deque

    # Build adjacency list
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    # Bellman-Ford to find shortest path from s to t
    def bellman_ford(s, t):
        dist = [float('inf')] * n
        dist[s] = 0
        for _ in range(n - 1):
            for u in range(n):
                if dist[u] == float('inf'):
                    continue
                for v, w in graph[u]:
                    if dist[v] > dist[u] + w:
                        dist[v] = dist[u] + w
        return dist[t] if dist[t] != float('inf') else -1

    # Try all nodes as starting point to find the shortest path from any node to t
    min_distance = float('inf')
    for s in range(n):
        distance = bellman_ford(s, n - 1)
        if distance != -1:
            min_distance = min(min_distance, distance)

    return min_distance if min_distance != float('inf') else -1

